<script setup lang="ts">import{computed}from"vue";import type{BaseRecord}from"@/types/records";type Country=BaseRecord&{nome?:string;codigo?:string};const props=defineProps<{countries:Country[]}>();const search=defineModel<string>('search',{required:true});const country=defineModel<string>('country',{required:true});const type=defineModel<string>('type',{required:true});const quality=defineModel<string>('quality',{required:true});const status=defineModel<string>('status',{required:true});const subscription=defineModel<string>('subscription',{required:true});const count=computed(()=>[search.value,country.value,type.value,quality.value,status.value!=='active'?status.value:'',subscription.value].filter(Boolean).length);const emit=defineEmits<{clear:[]}>();</script>
<template><section class="panel vod-filters"><div class="vod-filter-grid"><label class="form-field"><span>Pesquisar</span><input v-model.trim="search" placeholder="Título ou provider"></label><label class="form-field"><span>País</span><select v-model="country"><option value="">Todos</option><option v-for="c in countries" :key="c.id" :value="c.id">{{c.nome||c.codigo||c.id}}</option></select></label><label class="form-field"><span>Modalidade</span><select v-model="type"><option value="">Todas</option><option v-for="v in ['streaming','aluguer','compra','gratuito','broadcast','biblioteca','fisico','outro']" :key="v" :value="v">{{v}}</option></select></label><label class="form-field"><span>Qualidade</span><select v-model="quality"><option value="">Todas</option><option v-for="v in ['desconhecida','sd','hd','fhd','4k','8k','audio']" :key="v" :value="v">{{v}}</option></select></label><label class="form-field"><span>Estado</span><select v-model="status"><option value="active">Ativas</option><option value="inactive">Inativas</option><option value="all">Todas</option><option value="expired">Expiradas</option></select></label><label class="form-field"><span>Subscrição</span><select v-model="subscription"><option value="">Todas</option><option value="yes">Incluídas</option><option value="no">Não incluídas</option></select></label></div><button v-if="count" class="button button-secondary" @click="emit('clear')">Limpar filtros ({{count}})</button></section></template>
